const CACHE_NAME = 'map-tile-cache-v1';
const TILE_URL_PATTERN = /^https:\/\/[a-c]\.tile\.openstreetmap\.org\/\d+\/\d+\/\d+\.png$/;

// Install event - we don't pre-cache here because the tile array is generated by the app
self.addEventListener('install', () => {
  self.skipWaiting(); // Activate worker immediately
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName); // Clean up old caches
          }
        })
      );
    }).then(() => self.clients.claim()) // Take control of all pages immediately
  );
});

self.addEventListener('fetch', (event) => {
  const requestUrl = event.request.url;

  // Intercept OpenStreetMap tile requests
  if (TILE_URL_PATTERN.test(requestUrl)) {
    event.respondWith(
      caches.open(CACHE_NAME).then((cache) => {
        return cache.match(event.request).then((response) => {
          if (response) {
            // Cache Hit: Return the cached tile immediately
            return response;
          }

          // Cache Miss: Fetch from network
          return fetch(event.request).then((networkResponse) => {
            // Check if we received a valid response
            if (!networkResponse || networkResponse.status !== 200 || networkResponse.type !== 'basic' && networkResponse.type !== 'cors') {
              return networkResponse;
            }

            // Clone the response because it's a stream and can only be consumed once
            const responseToCache = networkResponse.clone();

            // Store the tile in cache for next time
            cache.put(event.request, responseToCache);

            return networkResponse;
          }).catch((error) => {
            console.error('Fetching tile failed:', error);
            // We could return a fallback "offline" tile here if we had one
            return new Response('', { status: 408, statusText: 'Offline' });
          });
        });
      })
    );
  }
});
